insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','demo-grammar-100','を · Marking the object',100,'grammar','{"text":"Use を after the thing affected by an action. The particle is written を and pronounced o. The verb comes at the end.","subject":"grammar","explanationEn":"Use を after the thing affected by an action. The particle is written を and pronounced o. The verb comes at the end.","explanationJa":"「を」は、{食|た}べるものや{読|よ}むものの{後|あと}に{置|お}きます。","examples":[{"japanese":"パンを{食|た}べます。","english":"I eat bread."},{"japanese":"{本|ほん}を{読|よ}みます。","english":"I read a book."},{"japanese":"{水|みず}を{飲|の}みます。","english":"I drink water."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000002','60000000-0000-4000-8000-000000000001','demo-grammar-101','に · Time and destination',101,'grammar','{"text":"Use に with a specific clock time. に can also mark a destination with movement verbs. These are different uses of the same particle.","subject":"grammar","explanationEn":"Use に with a specific clock time. に can also mark a destination with movement verbs. These are different uses of the same particle.","explanationJa":"{時間|じかん}を{言|い}うときや、{行|い}く{場所|ばしょ}を{言|い}うときに「に」を{使|つか}います。","examples":[{"japanese":"{七時|しちじ}に{起|お}きます。","english":"I get up at seven."},{"japanese":"{学校|がっこう}に{行|い}きます。","english":"I go to school."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000002') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000003','60000000-0000-4000-8000-000000000002','demo-grammar-100','ながら · Two actions together',100,'grammar','{"text":"Attach ながら to the verb’s ます-stem: 聞きます → 聞きながら. The same person does both actions at the same time. The main action is in the final clause.","subject":"grammar","explanationEn":"Attach ながら to the verb’s ます-stem: 聞きます → 聞きながら. The same person does both actions at the same time. The main action is in the final clause.","explanationJa":"「ます{形|けい}の{語幹|ごかん}＋ながら」は、{同|おな}じ{人|ひと}が{二|ふた}つのことを{同時|どうじ}にするときに{使|つか}います。","examples":[{"japanese":"{音楽|おんがく}を{聞|き}きながら、{料理|りょうり}をします。","english":"I cook while listening to music."},{"japanese":"{友達|ともだち}と{話|はな}しながら、{駅|えき}まで{歩|ある}きます。","english":"I walk to the station while talking with a friend."},{"japanese":"お{茶|ちゃ}を{飲|の}みながら、{本|ほん}を{読|よ}みます。","english":"I read a book while drinking tea."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000003') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000004','60000000-0000-4000-8000-000000000002','demo-grammar-101','てから · What happens next',101,'grammar','{"text":"Use a verb’s て-form + から to say that the following action happens after the first action is completed.","subject":"grammar","explanationEn":"Use a verb’s て-form + から to say that the following action happens after the first action is completed.","explanationJa":"「て{形|けい}＋から」は、{先|さき}にすることと、その{後|あと}にすることの{順番|じゅんばん}を{表|あらわ}します。","examples":[{"japanese":"{宿題|しゅくだい}をしてから、テレビを{見|み}ます。","english":"I watch TV after doing my homework."},{"japanese":"{手|て}を{洗|あら}ってから、ご{飯|はん}を{食|た}べます。","english":"I eat after washing my hands."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000004') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000005','60000000-0000-4000-8000-000000000001','demo-vocabulary-102','Everyday words',102,'vocabulary','{"text":"Read each word in context, then practice the vocabulary deck. Notice the particle and the verb, not only the isolated word.","subject":"vocabulary","explanationEn":"Read each word in context, then practice the vocabulary deck. Notice the particle and the verb, not only the isolated word.","explanationJa":"{単語|たんご}だけでなく、{文|ぶん}の{中|なか}で{使|つか}い{方|かた}を{見|み}ましょう。","examples":[{"japanese":"{水|みず}を{飲|の}みます。","english":"I drink water."},{"japanese":"{友達|ともだち}と{話|はな}します。","english":"I talk with a friend."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000005') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000006','60000000-0000-4000-8000-000000000001','demo-kanji-103','日 and 月 in context',103,'kanji','{"text":"Kanji readings depend on the word. Learn a whole word and its reading together; do not assume a character always has one pronunciation.","subject":"kanji","explanationEn":"Kanji readings depend on the word. Learn a whole word and its reading together; do not assume a character always has one pronunciation.","explanationJa":"{漢字|かんじ}は{言葉|ことば}によって{読|よ}み{方|かた}が{変|か}わります。{言葉|ことば}と{一緒|いっしょ}に{覚|おぼ}えましょう。","examples":[{"japanese":"{日曜日|にちようび}です。","english":"It is Sunday."},{"japanese":"{月曜日|げつようび}に{学校|がっこう}へ{行|い}きます。","english":"I go to school on Monday."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000006') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000007','60000000-0000-4000-8000-000000000001','demo-reading-104','A short morning routine',104,'reading','{"text":"Read the whole passage first. Identify the person, time and main action before answering the reading practice questions.","subject":"reading","explanationEn":"Read the whole passage first. Identify the person, time and main action before answering the reading practice questions.","explanationJa":"まず{全部|ぜんぶ}{読|よ}みましょう。だれが、いつ、{何|なに}をするか{考|かんが}えましょう。","examples":[{"japanese":"{田中|たなか}さんは{毎朝|まいあさ}{七時|しちじ}に{起|お}きます。パンを{食|た}べて、{八時|はちじ}に{学校|がっこう}へ{行|い}きます。","english":"Tanaka gets up at seven every morning, eats bread and goes to school at eight."},{"japanese":"{学校|がっこう}へ{行|い}くのは{八時|はちじ}です。","english":"The time for going to school is eight."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000007') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000008','60000000-0000-4000-8000-000000000002','demo-vocabulary-102','Words for daily plans',102,'vocabulary','{"text":"Read each word in context, then practice the vocabulary deck. Notice the particle and the verb, not only the isolated word.","subject":"vocabulary","explanationEn":"Read each word in context, then practice the vocabulary deck. Notice the particle and the verb, not only the isolated word.","explanationJa":"{単語|たんご}だけでなく、{文|ぶん}の{中|なか}で{使|つか}い{方|かた}を{見|み}ましょう。","examples":[{"japanese":"{明日|あした}の{予定|よてい}を{確認|かくにん}します。","english":"I check tomorrow’s schedule."},{"japanese":"{会議|かいぎ}は{午後|ごご}です。","english":"The meeting is in the afternoon."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000008') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000009','60000000-0000-4000-8000-000000000002','demo-kanji-103','会 and 社 in context',103,'kanji','{"text":"Kanji readings depend on the word. Learn a whole word and its reading together; do not assume a character always has one pronunciation.","subject":"kanji","explanationEn":"Kanji readings depend on the word. Learn a whole word and its reading together; do not assume a character always has one pronunciation.","explanationJa":"{漢字|かんじ}は{言葉|ことば}によって{読|よ}み{方|かた}が{変|か}わります。{言葉|ことば}と{一緒|いっしょ}に{覚|おぼ}えましょう。","examples":[{"japanese":"{会社|かいしゃ}で{働|はたら}いています。","english":"I work at a company."},{"japanese":"{会議|かいぎ}は{三時|さんじ}からです。","english":"The meeting starts at three."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000009') on conflict do nothing;
insert into public.lessons(id,course_id,slug,title,position,subject,body,published,review_status) select '81000000-0000-4000-8000-000000000010','60000000-0000-4000-8000-000000000002','demo-reading-104','A changed meeting time',104,'reading','{"text":"Read the whole passage first. Identify the person, time and main action before answering the reading practice questions.","subject":"reading","explanationEn":"Read the whole passage first. Identify the person, time and main action before answering the reading practice questions.","explanationJa":"まず{全部|ぜんぶ}{読|よ}みましょう。だれが、いつ、{何|なに}をするか{考|かんが}えましょう。","examples":[{"japanese":"{明日|あした}の{会議|かいぎ}は{二時|にじ}からの{予定|よてい}でしたが、{三時|さんじ}に{変|か}わりました。{場所|ばしょ}は{同|おな}じです。","english":"Tomorrow’s meeting was planned for two but has changed to three. The location is the same."},{"japanese":"{変|か}わったのは{時間|じかん}だけです。","english":"Only the time changed."}]}'::jsonb,true,'approved' where not exists(select 1 from public.lessons where id='81000000-0000-4000-8000-000000000010') on conflict do nothing;
