insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','を marks the direct object, the thing eaten. に and へ indicate other relationships; で often marks the place or means of an action.','「を」は{食|た}べるものの{後|あと}です。','I eat bread.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000001') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000001') on conflict do nothing;
