insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000002','93000000-0000-4000-8000-000000000006','で marks the place where an action happens. The studying happens at school. に and へ do not mark the location of this activity.','{勉強|べんきょう}する{場所|ばしょ}には「で」を{使|つか}います。','I study Japanese at school.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000002') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000001') on conflict do nothing;
