insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000014','93000000-0000-4000-8000-000000000053','Verb past plain form + ことがある describes a past experience. 行ったことがあります means ‘have been’. The other nouns do not form this experience pattern.','「{動詞|どうし}のた{形|けい}＋ことがある」は、{経験|けいけん}を{表|あらわ}します。','I have been to Japan.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000014') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
