insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000015','93000000-0000-4000-8000-000000000058','Attach ながら to the verb’s ます-stem: 聞きます → 聞きながら. It expresses two simultaneous actions by the same person; the main action follows.','「{動詞|どうし}のます{形|けい}の{語幹|ごかん}＋ながら」は、{二|ふた}つの{動作|どうさ}を{同時|どうじ}にすることを{表|あらわ}します。','Every morning, I make breakfast while listening to music.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000015') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
