insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000016','93000000-0000-4000-8000-000000000063','Verb て-form + から places the second action after completion of the first. してから means ‘after doing’. The other options cannot follow して in this sentence.','「て{形|けい}＋から」は、{先|さき}にすることと、その{後|あと}にすることの{順番|じゅんばん}を{表|あらわ}します。','I will watch TV after doing my homework.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000016') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
