insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000017','93000000-0000-4000-8000-000000000068','Verb て-form + もいいですか asks permission. 撮ってもいいですか means ‘May I take a photograph?’ The other choices do not form a permission question.','「て{形|けい}＋もいいですか」は、{許可|きょか}を{求|もと}める{表現|ひょうげん}です。','May I take a photograph here?' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000017') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
