insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000018','93000000-0000-4000-8000-000000000069','Verb ない-form without い + ければなりません expresses obligation. しなければなりません means ‘must do’. なりません completes this fixed construction.','「なければなりません」は、{必要|ひつよう}なことや{義務|ぎむ}を{表|あらわ}します。','I have an exam tomorrow, so I must study.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000018') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
