insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000019','93000000-0000-4000-8000-000000000074','Verb dictionary form + つもりです states an intention. 休むつもりです means ‘intend to be absent’. ながら requires a ます-stem; the other choices do not form the required predicate.','「{辞書形|じしょけい}＋つもりです」は、{自分|じぶん}の{意志|いし}や{予定|よてい}を{表|あらわ}します。','Because I am ill, I intend to stay home from school today.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000019') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
