insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000020','93000000-0000-4000-8000-000000000079','Verb ます-stem + やすい means ‘easy to do’. 読みやすい describes readability. ながら cannot be followed by です this way; たいな and すぎな are not valid endings here.','「ます{形|けい}の{語幹|ごかん}＋やすい」は、その{動作|どうさ}が{簡単|かんたん}だという{意味|いみ}です。','This book has large print and is easy to read.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000020') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
