insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000021','93000000-0000-4000-8000-000000000084','Verb ます-stem + すぎる means to do too much. Use its て-form, すぎて, to connect the excessive eating to the following consequence. すぎます, すぎる and すぎた do not supply that linking form.','「ます{形|けい}の{語幹|ごかん}＋すぎる」は、{程度|ていど}が{多|おお}すぎることを{表|あらわ}します。','Yesterday I ate too much cake and got a stomachache.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000021') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
