insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) select '92000000-0000-4000-8000-000000000022','93000000-0000-4000-8000-000000000085','Verb ます-stem + そうです expresses an appearance or imminent event based on what one observes. 降りそうです means ‘looks like it will rain’. The verb stem cannot take the other choices here.','「ます{形|けい}の{語幹|ごかん}＋そうです」は、{見|み}た{様子|ようす}から{判断|はんだん}する{表現|ひょうげん}です。','It looks as though it will rain, so let’s take an umbrella.' where not exists(select 1 from private.answer_keys where question_id='92000000-0000-4000-8000-000000000022') and exists(select 1 from pg_temp.task4_created_containers where id='91000000-0000-4000-8000-000000000005') on conflict do nothing;
